361.               form="collectionSettings"
362.               className="btn btn-success btn-extra-padding"
363.             >
364.               <span className="btn-label">
365.                 <Translate>Save</Translate>
366.               </span>
367.             </button>
368.           </div>
369.         </div>
370.       </div>
371.     </div>
372.   );
373. };
