     handleAddUser: () => {
       setSelectedUser({ role: UserRole.COLLABORATOR, username: '', email: '' });
       setSidePanelOpened(true);
     },

     handleResetPassword: async (user: UserSchema) => {
       await resetUserPassword(user.email);
     },
   };

   return (
     <>
       <UserList
